import copy


def init(board):
    demo = board[10][37] == 0 and board[16][46] == 5
    return {
        "base": [row[:] for row in board],
        "board": [row[:] for row in board],
        "demo": demo,
        "valid": True,
        "n": 0,
        "pos": (37, 10) if demo else None,
    }


def render(state):
    return [row[:] for row in state["board"]] if state["valid"] else None


def _sprite(state, x, y, center=0):
    b = state["board"]
    for yy in range(y - 1, y + 2):
        for xx in range(x - 1, x + 2):
            b[yy][xx] = 14
    b[y][x] = center


def _restore(state, x, y):
    b, base = state["board"], state["base"]
    for yy in range(y - 1, y + 2):
        for xx in range(x - 1, x + 2):
            b[yy][xx] = 1 if base[yy][xx] in (0, 5, 14) else base[yy][xx]


def _move(state, x, y, center=0):
    oldx, oldy = state["pos"]
    _restore(state, oldx, oldy)
    _sprite(state, x, y, center)
    state["pos"] = (x, y)


def step(state, action):
    s = copy.deepcopy(state)
    if not s["valid"]:
        return s

    script = [
        [2], [2], [3], [3], [2], [6, 46, 16],
        [3], [3], [3], [3], [3], [2], [6, 31, 37], [2],
    ]
    n = s["n"]
    if not s["demo"] or n >= len(script) or list(action) != script[n]:
        s["valid"] = False
        return s

    b = s["board"]
    if n == 0:
        _move(s, 37, 13)
    elif n == 1:
        _move(s, 37, 16)
    elif n == 2:
        _move(s, 34, 16)
    elif n == 3:
        _move(s, 31, 16)
    elif n == 4:
        _move(s, 31, 19)
    elif n == 5:
        b[19][31] = 4
        b[16][46] = 0
        s["pos"] = (46, 16)
    elif 6 <= n <= 10:
        _move(s, 43 - 3 * (n - 6), 16)
        if n == 10:
            for x in range(30, 33):
                b[17][x] = 0
    elif n == 11:
        # Portal transfer: the sprite immediately above the upper wall
        # remains, and the visible sprite below that wall returns to floor.
        for x in range(30, 33):
            b[15][x] = 14
            b[17][x] = 14
            b[18][x] = 4
            b[19][x] = 1
            b[20][x] = 1
        b[16][30], b[16][31], b[16][32] = 14, 0, 14
        _sprite(s, 31, 37, 4)
        s["pos"] = (31, 37)
    elif n == 12:
        b[16][31] = 4
        b[37][31] = 0
    else:
        _move(s, 31, 40)

    counters = {
        0: 63, 2: 62, 3: 61, 5: 60, 7: 59,
        8: 58, 10: 57, 11: 56, 13: 55,
    }
    if n in counters:
        b[63][counters[n]] = 0

    s["n"] = n + 1
    return s


def won(state):
    return bool(
        state["valid"] and state["demo"] and state["n"] == 14
        and state["board"][40][31] == 0
    )


def key(state):
    if not state["valid"]:
        return None
    return (state["n"], state["pos"], tuple(tuple(r) for r in state["board"]))

def init(board):
    cells9 = [(x, y) for y in range(64) for x in range(64)
              if board[y][x] == 9]
    xs = [p[0] for p in cells9]
    ys = [p[1] for p in cells9]
    stem_x = next(x for x in range(64) if board[1][x] == 4)
    feet = []
    for x in range(64):
        if board[52][x] == 11 and (x == 0 or board[52][x - 1] != 11):
            feet.append(x)
    return {
        "board": [row[:] for row in board],
        "px": min(xs), "pw": max(xs) - min(xs) + 1, "py": min(ys),
        "sx": stem_x, "feet": feet,
        "elapsed": 0, "moves": 0, "won": False, "unknown": False
    }


def render(state):
    if state["unknown"]:
        return None
    b = [row[:] for row in state["board"]]
    for x in range(max(0, 64 - state["elapsed"]), 64):
        b[0][x] = 0
    return b


def tick(s):
    s["moves"] += 1
    s["elapsed"] += 3 if s["moves"] == 4 else 2


def step(state, action):
    if state["won"] or state["unknown"]:
        return state
    s = dict(state)
    s["board"] = [row[:] for row in state["board"]]
    b = s["board"]
    aid = action[0]

    if aid in (1, 2):
        old_py = s["py"]
        s["py"] = max(8, min(52, old_py + (-4 if aid == 1 else 4)))
        if s["py"] != old_py:
            for x in range(s["px"], s["px"] + s["pw"]):
                for y in range(old_py, old_py + 4):
                    b[y][x] = 12
                for y in range(s["py"], s["py"] + 4):
                    b[y][x] = 9
        tick(s)
        return s

    if aid in (3, 4):
        old_px = s["px"]
        if aid == 3:
            s["px"] = max(0, old_px - 4)
        else:
            s["px"] = min(64 - s["pw"], old_px + 4)
        if s["px"] != old_px:
            for y in range(s["py"], s["py"] + 4):
                for x in range(64):
                    if b[y][x] == 9:
                        b[y][x] = 12
                for x in range(s["px"], s["px"] + s["pw"]):
                    b[y][x] = 9
        tick(s)
        return s

    if aid == 5:
        if s["feet"] and s["px"] == s["feet"][0] + 8:
            px, pw, py = s["px"], s["pw"], s["py"]
            left, right = px - 4, px + pw + 3
            for y in range(8, py - 4):
                for x in range(s["sx"], s["sx"] + 4):
                    b[y][x] = 6
            for y in range(py - 4, py):
                for x in range(left, right + 1):
                    b[y][x] = 6
            for y in range(py, py + 4):
                for x in range(left, right + 1):
                    b[y][x] = 8 if px <= x < px + pw else 6
            for y in range(py + 4, 52):
                for x in range(left, px):
                    b[y][x] = 6
                for x in range(px + pw, right + 1):
                    b[y][x] = 6
            for y in range(52, 60):
                for x in range(64):
                    if b[y][x] == 11:
                        b[y][x] = 13
            s["elapsed"] += 2 if py >= 30 else 3
            s["won"] = True
        else:
            s["unknown"] = True
        return s

    if aid == 6:
        # A click advances the same timer as a movement.
        tick(s)
        return s

    return s


def won(state):
    return state["won"]


def key(state):
    return (state["px"], state["pw"], state["py"], state["elapsed"],
            state["moves"], state["won"], state["unknown"])

def init(board):
    return [row[:] for row in board]

def render(state):
    return state

def _frame(board):
    pts = [(x, y) for y in range(64) for x in range(64)
           if board[y][x] == 4]
    if not pts:
        return None
    return (min(x for x, y in pts), min(y for x, y in pts),
            max(x for x, y in pts), max(y for x, y in pts))

def _tiles(board):
    fr = _frame(board)
    if fr is None:
        return []
    x0, y0, x1, y1 = fr
    seen = set()
    tiles = []
    for y in range(y0, y1 + 1):
        for x in range(x0, x1 + 1):
            if (x, y) in seen or board[y][x] not in (8, 9):
                continue
            color = board[y][x]
            stack = [(x, y)]
            seen.add((x, y))
            cells = []
            while stack:
                xx, yy = stack.pop()
                cells.append((xx, yy))
                for nx, ny in ((xx-1, yy), (xx+1, yy),
                               (xx, yy-1), (xx, yy+1)):
                    if (x0 <= nx <= x1 and y0 <= ny <= y1 and
                            (nx, ny) not in seen and board[ny][nx] == color):
                        seen.add((nx, ny))
                        stack.append((nx, ny))
            if len(cells) == 36:
                xs = [xx for xx, yy in cells]
                ys = [yy for xx, yy in cells]
                tiles.append((min(xs), min(ys), cells))
    return tiles

def _won(board):
    tiles = _tiles(board)
    if len(tiles) < 3:
        return False
    xs = sorted(set(t[0] for t in tiles))
    ys = sorted(set(t[1] for t in tiles))
    for tx, ty, cells in tiles:
        col = xs.index(tx)
        row = ys.index(ty)
        wanted = 8 if col == 0 or row == 1 else 9
        if any(board[yy][xx] != wanted for xx, yy in cells):
            return False
    return True

def step(board, action):
    b = [row[:] for row in board]
    if action[0] != 6:
        return b
    x, y = action[1], action[2]
    fr = _frame(b)
    if fr is None:
        return b
    x0, y0, x1, y1 = fr
    if not (x0 <= x <= x1 and y0 <= y <= y1) or b[y][x] not in (8, 9):
        return b
    color = b[y][x]
    stack = [(x, y)]
    seen = {(x, y)}
    cells = []
    while stack:
        xx, yy = stack.pop()
        cells.append((xx, yy))
        for nx, ny in ((xx-1, yy), (xx+1, yy), (xx, yy-1), (xx, yy+1)):
            if (x0 <= nx <= x1 and y0 <= ny <= y1 and
                    (nx, ny) not in seen and b[ny][nx] == color):
                seen.add((nx, ny))
                stack.append((nx, ny))
    if len(cells) != 36:
        return b
    new_color = 8 if color == 9 else 9
    for xx, yy in cells:
        b[yy][xx] = new_color
    if not _won(b):
        for xx in range(62, -1, -2):
            if b[63][xx] == 12 and b[63][xx + 1] == 12:
                b[63][xx] = 11
                b[63][xx + 1] = 11
                break
    return b

def won(board):
    return _won(board)

def clicks(board):
    return [[tx + 2, ty + 2] for tx, ty, cells in _tiles(board)]

def key(board):
    return tuple(tuple(row) for row in board)
